import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String customerId = req.getParameter("customer_id");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Basic date format check (YYYY-MM-DD)
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - sort column is user-controlled
        String query = buildReportQuery(reportType, startDate, endDate, customerId, sortCol);
        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end,
                                     String customerId, String sortCol) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT r.id, r.created_at, r.amount, c.name ");
        sb.append("FROM reports r JOIN customers c ON r.customer_id = c.id ");
        sb.append("WHERE r.report_type = '").append(type).append("' ");
        sb.append("AND r.created_at BETWEEN '").append(start).append("' AND '").append(end).append("' ");

        if (customerId != null && !customerId.isEmpty()) {
            // customerId is validated as numeric below
            if (customerId.matches("^[0-9]+$")) {
                sb.append("AND r.customer_id = ").append(customerId).append(" ");
            }
        }

        // Sort column - validated against allowlist... or is it?
        String safeSort = sanitizeSortColumn(sortCol);
        sb.append("ORDER BY ").append(safeSort);

        return sb.toString();
    }

    private String sanitizeSortColumn(String col) {
        // Intended allowlist but implementation has a flaw:
        // allows expressions containing allowed substrings
        String[] allowed = {"id", "created_at", "amount", "name"};
        if (col == null || col.isEmpty()) return "r.created_at";

        String lower = col.toLowerCase().trim();
        for (String a : allowed) {
            if (lower.contains(a)) {
                return col;  // Returns ORIGINAL unsanitized input
            }
        }
        return "r.created_at";
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        String[] valid = {"sales", "returns", "inventory", "audit"};
        for (String v : valid) {
            if (v.equals(type)) return true;
        }
        return false;
    }

    private boolean isValidDate(String date) {
        if (date == null) return false;
        return date.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(rs.getString(i)).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
